var i=`0671-kelewele`;var t=`world-0671`;var a=`GH`;var s=`western-africa`;var o=4;var r=35;var l={en:`Kelewele`,ua:`Келевеле`};var g={en:`Kelewele is a Ghana classic prepared with plantain, ginger root, peanut. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Келевеле, страва кухні країни Гана зі складниками: плантан, корінь імбиру, арахіс. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var d=[{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:7,i:[[`plantain`,650,`g`],[`ginger-root`,25,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:7,i:[[`hot-paprika`,7,`g`],[`ground-cloves`,2,`g`],[`ground-nutmeg`,2,`g`],[`table-salt`,null,`to_taste`]]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 18 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 18 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:18,i:[[`sunflower-oil`,600,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`peanut`,60,`g`]]}];var u={slug:i,id:t,country:`GH`,region:s,servings:4,minutes:35,title:l,text:g,steps:d};export{a as country,u as default,t as id,r as minutes,s as region,o as servings,i as slug,d as steps,g as text,l as title};